def measure_rules(rule_asts):
    """Returns (atom order list, node count).  Raises E_LIMIT on violation."""
    atoms = {}
    nodes = 0
    longest = 0
    stack = []
    for _is_allow, ast in rule_asts:
        stack.append(ast)
        while stack:
            node = stack.pop()
            nodes += 1
            tag = node[0]
            if tag == 'and' or tag == 'or':
                args = node[1]
                if len(args) > MAX_ARGS:
                    raise CodedError('E_LIMIT')
                stack.extend(args)
            elif tag == 'not':
                stack.append(node[1])
            elif tag == 'const':
                pass
            else:
                path = node[1]
                if len(path) > longest:
                    longest = len(path)
                if node not in atoms:
                    atoms[node] = None
    if nodes > MAX_NODES:
        raise CodedError('E_LIMIT')
    if longest > MAX_ATOM_PATH:
        raise CodedError('E_LIMIT')
    if len(atoms) > MAX_ATOMS:
        raise CodedError('E_LIMIT')
    return list(atoms), nodes


